-- Geographic validation. Coordinates and polygons outside Bangladesh or with
-- an invalid SRID/geometry are rejected at the database boundary as well as in
-- the application service.
ALTER TABLE "farm_locations" ADD CONSTRAINT "farm_locations_location_srid_check" CHECK (
  "location" IS NULL OR ST_SRID("location") = 4326
);
ALTER TABLE "farm_locations" ADD CONSTRAINT "farm_locations_location_bangladesh_check" CHECK (
  "location" IS NULL OR (
    ST_X("location") BETWEEN 88.0 AND 92.7
    AND ST_Y("location") BETWEEN 20.5 AND 26.7
  )
);
ALTER TABLE "farm_locations" ADD CONSTRAINT "farm_locations_boundary_valid_check" CHECK (
  "boundary" IS NULL OR (
    ST_SRID("boundary") = 4326
    AND ST_GeometryType("boundary") = 'ST_Polygon'
    AND ST_IsValid("boundary")
  )
);
ALTER TABLE "land_parcels" ADD CONSTRAINT "land_parcels_boundary_valid_check" CHECK (
  "boundary" IS NULL OR (
    ST_SRID("boundary") = 4326
    AND ST_GeometryType("boundary") = 'ST_Polygon'
    AND ST_IsValid("boundary")
  )
);

-- Non-negative area and bounded agronomic measurements.
ALTER TABLE "farms" ADD CONSTRAINT "farms_area_value_check" CHECK (
  "area_value" >= 0 AND "total_area_hectares" >= 0
);
ALTER TABLE "land_parcels" ADD CONSTRAINT "land_parcels_area_value_check" CHECK (
  "area_value" >= 0 AND "area_hectares" >= 0
);
ALTER TABLE "farm_soil_profiles" ADD CONSTRAINT "farm_soil_profiles_ph_check" CHECK (
  "ph" IS NULL OR ("ph" >= 0 AND "ph" <= 14)
);
ALTER TABLE "farm_soil_profiles" ADD CONSTRAINT "farm_soil_profiles_organic_matter_check" CHECK (
  "organic_matter_percent" IS NULL OR ("organic_matter_percent" >= 0 AND "organic_matter_percent" <= 100)
);
ALTER TABLE "farm_irrigations" ADD CONSTRAINT "farm_irrigations_capacity_check" CHECK (
  "capacity_liters_per_minute" IS NULL OR "capacity_liters_per_minute" >= 0
);
ALTER TABLE "farm_irrigations" ADD CONSTRAINT "farm_irrigations_command_area_check" CHECK (
  "command_area_hectares" IS NULL OR "command_area_hectares" >= 0
);
ALTER TABLE "farm_irrigations" ADD CONSTRAINT "farm_irrigations_frequency_check" CHECK (
  "frequency_per_week" IS NULL OR ("frequency_per_week" >= 0 AND "frequency_per_week" <= 21)
);

-- Soil and irrigation rows repeat the farm tenant key; enforce the same match
-- and immutability guarantees used by land parcels.
DO $$
BEGIN
  PERFORM "cropsy_assert_tenant_match"('farm_soil_profiles', 'farms', 'farm_id');
  PERFORM "cropsy_assert_tenant_match"('farm_irrigations', 'farms', 'farm_id');
END;
$$;

CREATE CONSTRAINT TRIGGER "farm_soil_profiles_tenant_match_check"
AFTER INSERT OR UPDATE OF "organization_id", "farm_id" ON "farm_soil_profiles"
DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW EXECUTE FUNCTION "cropsy_enforce_tenant_match"('farms', 'farm_id');

CREATE CONSTRAINT TRIGGER "farm_irrigations_tenant_match_check"
AFTER INSERT OR UPDATE OF "organization_id", "farm_id" ON "farm_irrigations"
DEFERRABLE INITIALLY IMMEDIATE
FOR EACH ROW EXECUTE FUNCTION "cropsy_enforce_tenant_match"('farms', 'farm_id');

DROP TRIGGER IF EXISTS "farms_tenant_immutable_check" ON "farms";
CREATE CONSTRAINT TRIGGER "farms_tenant_immutable_check"
AFTER UPDATE OF "organization_id" ON "farms"
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW EXECUTE FUNCTION "cropsy_enforce_tenant_immutable"('land_parcels', 'farm_id', 'cultivations', 'farm_id', 'farm_activities', 'farm_id', 'harvests', 'farm_id', 'farm_soil_profiles', 'farm_id', 'farm_irrigations', 'farm_id');
